import{_ as e,o as a,c as n,ae as o}from"./chunks/framework.Dn6zxbF8.js";const f=JSON.parse('{"title":"Pattern matching in function heads and control-flow","description":"","frontmatter":{"id":"1475937194","title":"Pattern matching in function heads and control-flow","state":"Approved","created":"2025-03-16T00:00:00.000Z","tags":["pattern-matching"],"category":"Elixir"},"headers":[],"relativePath":"adrs/1475937194/README.md","filePath":"adrs/1475937194/README.md"}'),i={name:"adrs/1475937194/README.md"};function r(s,t,l,c,h,d){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="pattern-matching-in-function-heads-and-control-flow" tabindex="-1">Pattern matching in function heads and control-flow <a class="header-anchor" href="#pattern-matching-in-function-heads-and-control-flow" aria-label="Permalink to &quot;Pattern matching in function heads and control-flow&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Pattern matching in function heads should be used exclusively for control flow and not as a convenient way to extract values out of maps or structs.</p><p>This helps indicate to the reader of the code that the pattern matching influences the control-flow of the code and as-such runtime behaviour.</p><p>This is also outlined <a href="https://hexdocs.pm/elixir/main/code-anti-patterns.html#complex-extractions-in-clauses" target="_blank" rel="noreferrer">in the official docs as an anti-pattern</a></p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li>You <strong>MUST</strong> pattern matching in function heads for control-flow purposes.</li><li>You <strong>MUST NOT</strong> use pattern matching in function heads as a convenience for destructuring variables out into the function body.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://hexdocs.pm/elixir/main/code-anti-patterns.html#complex-extractions-in-clauses" target="_blank" rel="noreferrer">https://hexdocs.pm/elixir/main/code-anti-patterns.html#complex-extractions-in-clauses</a></li></ul>',9)])])}const p=e(i,[["render",r]]);export{f as __pageData,p as default};
